import { defineAsamOptions, defineAsamDictSource } from '@asam-ui/ui';
import { sourceItems } from './Sources.js';
import * as pro from '@asam-ui/pro';
import type {
	AsamFieldDefinition,
	AsamFieldViewBinding,
	AsamHierarchyService,
	AsamPagedOptionService,
	AsamTemporalKind
} from '@asam-ui/pro/components';

export interface CatalogCase {
	id: string;
	factory: string;
	variant: string;
	input: unknown;
	invalid: unknown;
	binding: AsamFieldViewBinding;
}
export const choiceOptions = [
	{ value: 0, label: '零值' },
	{ value: '0', label: '字符串零' },
	{ value: false, label: '否' },
	{ value: 'retired', label: '已停用', disabled: true }
];
export function createCatalog() {
	const cases: CatalogCase[] = [];
	const add = (
		factory: string,
		variant: string,
		field: AsamFieldDefinition,
		input: unknown,
		invalid: unknown,
		extra: Omit<AsamFieldViewBinding, 'field'> = {}
	) =>
		cases.push({
			id: field.key,
			factory,
			variant,
			input,
			invalid,
			binding: { field, ...extra }
		});
	for (const kind of ['text', 'textarea'] as const)
		add(
			'defineAsamFields',
			kind,
			{
				key: kind,
				label: kind === 'text' ? '姓名与很长的中文标签测试可读换行' : '正文原文',
				kind
			},
			kind === 'text' ? '0' : '保留\n原文 ',
			{}
		);
	for (const kind of ['single', 'multiple'] as const)
		for (const control of kind === 'single'
			? ['select', 'radio', 'radio-button']
			: ['select', 'checkbox', 'checkbox-button']) {
			const key = `${kind}_${control.replaceAll('-', '_')}`;
			const source = defineAsamOptions().static({ options: choiceOptions });
			const field: AsamFieldDefinition =
				kind === 'single'
					? {
							key,
							label: key,
							kind,
							control: control as 'select' | 'radio' | 'radio-button',
							source
						}
					: {
							key,
							label: key,
							kind,
							control: control as 'select' | 'checkbox' | 'checkbox-button',
							source
						};
			add(
				'defineAsamFields',
				`${kind}/${control}`,
				field,
				kind === 'single' ? false : [0, '0', false],
				{}
			);
		}
	add(
		'createAsamNumberField',
		'number',
		pro.createAsamNumberField({ key: 'number', label: '数值', precision: 2 }),
		0,
		'0'
	);
	for (const multiple of [false, true]) {
		const key = `native_remote_${multiple}`;
		const remote = {
			search: (keyword: string) =>
				defineAsamOptions().api({ api: async () => sourceItems(), params: keyword }),
			resolve: (values: readonly (string | number | boolean)[]) =>
				defineAsamOptions().api({
					api: async () =>
						(await sourceItems()).filter((item) => values.includes(item.value)),
					params: [...values]
				})
		};
		add(
			'defineAsamFields',
			`remote-search-resolve/${multiple}`,
			multiple
				? { key, label: key, kind: 'multiple', remote }
				: { key, label: key, kind: 'single', remote },
			multiple ? [0, '0'] : 0,
			{}
		);
	}
	for (const value of ['missing', 'retired'])
		add(
			'defineAsamFields',
			`static-preserve/${value}`,
			{
				key: `preserve_${value}`,
				label: `保值${value}`,
				kind: 'single',
				source: defineAsamOptions().static({ options: choiceOptions })
			},
			value,
			{}
		);
	for (const kind of ['api', 'request', 'dict'] as const)
		for (const multiple of [false, true]) {
			const source =
				kind === 'api'
					? defineAsamOptions().api({
							api: sourceItems,
							params: undefined,
							transform: (items) => items,
							cache: { ttlMs: 1000 }
						})
					: kind === 'request'
						? defineAsamOptions().request({
								request: { url: '/fixture-options', method: 'get' }
							})
						: defineAsamDictSource({
								dictType: 'fixture-number',
								dictValueType: 'number'
							});
			const key = `source_${kind}_${multiple}`;
			add(
				'defineAsamFields',
				`${kind}/${multiple}`,
				multiple
					? { key, label: key, kind: 'multiple', source }
					: { key, label: key, kind: 'single', source },
				multiple ? [0] : 0,
				{}
			);
		}
	add(
		'createAsamNumberRangeField',
		'open',
		pro.createAsamNumberRangeField({ key: 'number_range', label: '数值区间', allowOpen: true }),
		{ start: 0, end: null },
		null
	);
	for (const storageUnit of ['major', 'minor'] as const)
		add(
			'createAsamMoneyField',
			storageUnit,
			pro.createAsamMoneyField({
				key: `money_${storageUnit}`,
				label: `金额${storageUnit}`,
				currency: 'CNY',
				storageUnit,
				precision: 2
			}),
			storageUnit === 'major' ? 12.34 : 1234,
			'12.34'
		);
	add(
		'createAsamPasswordField',
		'masked',
		pro.createAsamPasswordField({ key: 'password', label: '密码' }),
		'never-show-secret',
		0
	);
	add(
		'createAsamTagField',
		'candidates',
		pro.createAsamTagField({
			key: 'tags',
			label: '标签',
			candidates: () => [{ value: '0', label: '标签零' }]
		}),
		['0'],
		[0]
	);
	add(
		'createAsamMentionField',
		'text',
		pro.createAsamMentionField({
			key: 'mention',
			label: '提及',
			candidates: () => [{ value: 'user', label: '用户' }]
		}),
		'@user 保留原文',
		{}
	);
	const captcha = pro.createAsamCaptchaField({
		key: 'captcha',
		label: '验证码',
		target: () => 'mock-target',
		service: async () => {}
	});
	add('createAsamCaptchaField', 'secret', captcha, '135790', 0, { sensitive: true });
	const service: AsamPagedOptionService = {
		page: async () => ({ items: [{ value: 0, label: '分页零' }], next: null }),
		resolve: async (values) => values.map((value) => ({ value, label: `分页${value}` }))
	};
	for (const multiple of [false, true])
		add(
			'createAsamPagedSelectField',
			`${multiple}`,
			pro.createAsamPagedSelectField({
				key: `paged_${multiple}`,
				label: '分页选择',
				service,
				multiple
			}),
			multiple ? [0] : 0,
			{}
		);
	add(
		'createAsamSuggestionField',
		'suggestion',
		pro.createAsamSuggestionField({ key: 'suggestion', label: '远程建议', service }),
		'原始建议文本',
		0
	);
	const leaf = { value: 'child', label: '子级', leaf: true },
		root = { value: 'root', label: '根级', leaf: false, children: [leaf] };
	const hierarchy: AsamHierarchyService = {
		roots: async () => [root],
		children: async () => [leaf],
		paths: async (values) => values.map(() => [root, leaf])
	};
	for (const control of ['cascader', 'tree'] as const)
		for (const multiple of [false, true])
			add(
				'createAsamHierarchyField',
				`${control}/${multiple}`,
				pro.createAsamHierarchyField({
					key: `${control}_${multiple}`,
					label: `${control}层级`,
					control,
					multiple,
					service: hierarchy
				}),
				control === 'cascader'
					? multiple
						? [['root', 'child']]
						: ['root', 'child']
					: multiple
						? ['child']
						: 'child',
				{}
			);
	add(
		'createAsamRegionField',
		'versioned',
		pro.createAsamRegionField({
			key: 'region',
			label: '地区',
			dataset: {
				version: 'fixture-1',
				license: 'CC0',
				levels: ['一级', '二级'],
				nodes: [root]
			}
		}),
		['root', 'child'],
		{}
	);
	const values: Record<AsamTemporalKind, unknown> = {
		date: '2026-10-18',
		time: '12:30:00',
		datetime: '2026-10-18T04:30:00.000Z',
		week: '2026-W42',
		month: '2026-10',
		quarter: '2026-Q4',
		year: '2026'
	};
	for (const kind of Object.keys(values) as AsamTemporalKind[])
		for (const range of [false, true])
			for (const storage of kind === 'datetime'
				? (['iso', 'epoch', 'date'] as const)
				: [undefined]) {
				const value =
					storage === 'epoch' ? 0 : storage === 'date' ? new Date(0) : values[kind];
				add(
					'createAsamTemporalField',
					`${kind}/${range}/${storage ?? 'calendar'}`,
					pro.createAsamTemporalField({
						key: `${kind}_${range}_${storage ?? 'calendar'}`,
						label: `${kind}${range ? '范围' : ''}`,
						kind,
						range,
						storage
					}),
					range ? { start: value, end: null } : value,
					'invalid'
				);
			}
	add(
		'createAsamSwitchField',
		'boolean',
		pro.createAsamSwitchField({ key: 'switch_bool', label: '开关' }),
		false,
		'0'
	);
	add(
		'createAsamSwitchField',
		'scalar',
		pro.createAsamSwitchField({
			key: 'switch_scalar',
			label: '标量开关',
			activeValue: '0',
			inactiveValue: 0
		}),
		0,
		false
	);
	for (const range of [false, true])
		add(
			'createAsamSliderField',
			`${range}`,
			pro.createAsamSliderField({ key: `slider_${range}`, label: '滑块', range }),
			range ? [0, 100] : 0,
			'0'
		);
	add(
		'createAsamRateField',
		'half',
		pro.createAsamRateField({ key: 'rate', label: '评分', inputProps: { allowHalf: true } }),
		0,
		'0'
	);
	add(
		'createAsamColorField',
		'alpha',
		pro.createAsamColorField({ key: 'color', label: '颜色', inputProps: { showAlpha: true } }),
		'#123456',
		{}
	);
	add(
		'createAsamSegmentedField',
		'dynamic',
		pro.createAsamSegmentedField({
			key: 'segmented',
			label: '分段',
			options: () => choiceOptions
		}),
		false,
		{}
	);
	add(
		'createAsamTagFilterField',
		'multiple',
		pro.createAsamTagFilterField({
			key: 'tag_filter',
			label: '标签筛选',
			options: () => choiceOptions
		}),
		[0, false],
		{}
	);
	for (const multiple of [false, true])
		add(
			'createAsamCardField',
			`${multiple}`,
			multiple
				? pro.createAsamCardField({
						key: 'card_many',
						label: '多选卡片',
						multiple: true,
						options: () => choiceOptions
					})
				: pro.createAsamCardField({
						key: 'card_one',
						label: '单选卡片',
						options: () => choiceOptions
					}),
			multiple ? [0, false] : false,
			{}
		);
	const resolve = async (ids: readonly (string | number)[]) =>
		ids.map((id) => ({ id, name: `资源${id}`, url: '/fixture.txt' }));
	for (const multiple of [false, true])
		add(
			'createAsamResourceField',
			`${multiple}`,
			pro.createAsamResourceField({
				key: `resource_${multiple}`,
				label: '资源',
				multiple,
				services: {
					upload: async () => {
						throw new Error('fixture没有写服务');
					},
					resolve
				}
			}),
			multiple ? [0, '0'] : 0,
			false,
			{ reader: pro.createAsamResourceDisplayReader(resolve, multiple) }
		);
	add(
		'createAsamRichTextField',
		'document',
		pro.createAsamRichTextField({ key: 'richtext', label: '安全富文本' }),
		{
			type: 'doc',
			content: [
				{ type: 'paragraph', content: [{ type: 'text', text: '<script>safe</script>' }] }
			]
		},
		'<p>HTML不导入</p>'
	);
	add(
		'createAsamMarkdownField',
		'markdown',
		pro.createAsamMarkdownField({ key: 'markdown', label: '安全Markdown' }),
		'# 保留 Markdown\n<script>unsafe()</script>',
		{}
	);
	add(
		'createAsamEditorField',
		'markdown-generic',
		pro.createAsamEditorField('markdown', { key: 'editor_generic', label: '通用编辑工厂' }),
		'原文 ',
		{}
	);
	return cases;
}

import type { AsamDataProvider } from '@asam-ui/ui';

/** 确定性只读fixture；真实业务来源由消费应用替换。 */
export const sourceState = { fail: false, revision: 1, calls: [] as string[] };
export async function sourceItems() {
	sourceState.calls.push(`read-${sourceState.revision}`);
	if (sourceState.fail) throw new Error('fixture读取失败');
	return [
		{ value: 0, label: `来源版本${sourceState.revision}零` },
		{ value: '0', label: `来源版本${sourceState.revision}字符串零` }
	];
}
export const sourceProvider: AsamDataProvider = {
	request: async () => sourceItems(),
	dict: {
		get: async () => (await sourceItems()).filter((item) => typeof item.value === 'number'),
		refresh: async () => {
			if (sourceState.fail) throw Error('字典刷新失败');
		}
	}
};

import { createApp } from 'vue';
import { provideAsamData } from '@asam-ui/ui';
import { sourceProvider } from './Sources.js';
import 'element-plus/dist/index.css';
import '@asam-ui/ui/style.css';
import '@asam-ui/pro/style.css';
import Example from './Example.vue';
const app = createApp(Example);
provideAsamData(app, sourceProvider);
app.mount('#app');

import { createApp as createOwnerApp } from 'vue';
import { AsamI18nKey } from '@asam-ui/ui/i18n';
import type { AsamI18n } from '@asam-ui/ui/i18n';
import { createApp } from 'vue';
import { provideAsamData } from '@asam-ui/ui';
import { sourceProvider } from '../tests/v2/field-modes/Sources.js';
import 'element-plus/dist/index.css';
import '@asam-ui/ui/style.css';
import '@asam-ui/pro/style.css';
import Example from '../tests/v2/field-modes/Example.vue';
export async function mountWebsiteExample(
	element: Element,
	onError: (error: unknown) => void,
	i18n?: AsamI18n
) {
	const apps: ReturnType<typeof createOwnerApp>[] = [];
	const createApp: typeof createOwnerApp = (...args) => {
		const app = createOwnerApp(...args);
		if (i18n) app.provide(AsamI18nKey, i18n);
		app.config.errorHandler = onError;
		apps.push(app);
		return app;
	};

	const app = createApp(Example);
	provideAsamData(app, sourceProvider);
	app.mount(element);

	return () => {
		for (const app of apps.reverse()) app.unmount();
	};
}
